  border-top: 1px solid var(--c-me-border) !important;
  border-radius: 0 1px 0 0 !important;
  transform: rotate(45deg) !important;
  z-index: 1 !important;
}

/* ── 表情包、图片与全类型卡片深度脱壳 ── */
