.msg-bubble-wrapper:has(.gift-ig-container) .bubble-them-custom,
.msg-bubble-wrapper:has(.bond-card-bubble) .bubble-me-custom,
.msg-bubble-wrapper:has(.bond-card-bubble) .bubble-them-custom,
.bubble-me-custom:has(img[alt="sticker"]),
.bubble-them-custom:has(img[alt="sticker"]),
