  min-height: auto !important;
  min-width: 0 !important;
}

/* 消除脱壳气泡的尾巴 */
.msg-bubble-wrapper:has(img[alt="sticker"]) .bubble-me-custom::before,
.msg-bubble-wrapper:has(img[alt="sticker"]) .bubble-me-custom::after,
.msg-bubble-wrapper:has(img[alt="sticker"]) .bubble-them-custom::before,
.msg-bubble-wrapper:has(img[alt="sticker"]) .bubble-them-custom::after,
.msg-bubble-wrapper:has(.msg-image-wrapper) .bubble-me-custom::before,
